// @ts-nocheck
// Generated by scheduler/tools/build-maintenance-road.mjs from the board's road files;
// `npm run build` writes it again. Never edited by hand.
const window = {};

// ── trip-shape.js
/* ==========================================================================
   Rux Scheduler — TRIP SHAPE, a trip's legs, routes, papers and contacts
   --------------------------------------------------------------------------
   The one reading of how a trip runs: its legs, each one time a bus leaves
   the yard and comes back, in date order; each leg's routes; and which
   itinerary files and day-of contacts each leg is handed. A trip is read
   with `trip_legs(*, trip_routes(*))`, `trip_documents` and
   `trip_contacts`; a row names its leg by `leg_id`, or its route by
   `route_id`.

   THE FIRST LEG STANDS IN FOR A LEG WITH NONE OF ITS OWN. A file or a
   contact with no leg is the trip's, and the first leg's with it; a later
   leg is handed its own, or the first leg's while it has none, so a
   customer's one paper and one set of contacts for the whole trip are
   entered once. On a trip of one leg every row is that leg's.

   Nothing here reads the page or the database, and it needs nothing loaded
   first.
   ========================================================================== */
(() => {
  'use strict';

  const clean = v => String(v ?? '').trim();
  const day = v => clean(v).slice(0, 10);
  // The old words, in the order the legs they name run.
  const WORD_ORDER = { outbound: 0, return: 1 };

  /* A trip's legs by date, each with its number from 1 and its routes by
     position. Two legs on one day keep the order of the words they mirror,
     then the order they were made, and a leg with no date comes last. */
  function legsOf(trip) {
    const legs = (trip?.trip_legs || []).map(l => ({
      id: l.id,
      word: l.leg ?? null,
      kind: l.kind === 'one_way' ? 'one_way' : 'round_trip',
      start: day(l.start_date) || null,
      end: day(l.end_date) || day(l.start_date) || null,
      busCount: Number.isInteger(l.bus_count) ? l.bus_count : null,
      hotelBooked: !!l.hotel_booked,
      hotelNumber: clean(l.hotel_itinerary_number) || null,
      routes: [...(l.trip_routes || [])].sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
        .map(r => ({ id: r.id, position: r.position ?? 1, name: clean(r.name) || null })),
      created: l.created_at || '',
    }));
    legs.sort((a, b) => (!a.start - !b.start) || (a.start || '').localeCompare(b.start || '')
      || (WORD_ORDER[a.word] ?? 2) - (WORD_ORDER[b.word] ?? 2)
      || a.created.localeCompare(b.created));
    return legs.map((l, i) => ({ ...l, number: i + 1 }));
  }
  const legOf = (trip, legId) => legsOf(trip).find(l => l.id === legId) ?? null;
  const firstLeg = trip => legsOf(trip)[0] ?? null;
  // The leg an old word names, while rows still carry the word.
  const legOfWord = (trip, word) => legsOf(trip).find(l => l.word === (word || 'outbound')) ?? null;
  // "2 of 3" on a trip of several legs, and nothing on a trip of one.
  function legLabel(trip, legId) {
    const legs = legsOf(trip);
    const leg = legs.find(l => l.id === legId);
    return leg && legs.length > 1 ? `${leg.number} of ${legs.length}` : '';
  }
  /* A trip's days: `first`, the day its first leg starts, and `last`, the
     latest day any leg ends; null for a trip read without its legs. */
  function daysOf(trip) {
    const legs = legsOf(trip).filter(l => l.start);
    if (!legs.length) return null;
    return { first: legs[0].start, last: legs.reduce((d, l) => (l.end > d ? l.end : d), legs[0].end) };
  }
  /* A SPLIT, the drop-off and the pickup: a trip whose first leg is one way
     and that has a later leg. Every leg after the first is its pickup,
     bringing the group home; a trip of one one-way leg is one way. */
  const isSplit = trip => { const legs = legsOf(trip); return legs.length > 1 && legs[0].kind === 'one_way'; };
  const isPickup = (trip, legId) => isSplit(trip) && (legOf(trip, legId)?.number ?? 1) > 1;
  // The leg a route is on.
  const legOfRoute = (trip, routeId) => legsOf(trip).find(l => l.routes.some(r => r.id === routeId)) ?? null;

  /* A leg's rows of a kind that names a leg, as the rule above hands them:
     on a trip of one leg, all of them; the first leg's are those naming it
     or no leg we know; a later leg's are its own, or the first leg's while
     it has none. */
  function forLeg(trip, legId, rows) {
    const legs = legsOf(trip);
    if (legs.length <= 1) return rows;
    const first = legs[0].id;
    const known = new Set(legs.map(l => l.id));
    const firsts = rows.filter(r => !r.leg_id || r.leg_id === first || !known.has(r.leg_id));
    if (legId === first) return firsts;
    const own = rows.filter(r => r.leg_id === legId);
    return own.length ? own : firsts;
  }

  /* THE ITINERARY, by the office's rule: a file whose type is Itinerary and
     no other, so a file named after one is not one. A leg's are newest
     first, and the first is the one its drivers are handed. */
  const isItinerary = d => clean(d?.label).toLowerCase() === 'itinerary';
  const newestFirst = (a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0);
  const allItineraries = trip => (trip?.trip_documents || []).filter(isItinerary).sort(newestFirst);
  const itinerariesFor = (trip, legId) => forLeg(trip, legId, allItineraries(trip));
  const itineraryFor = (trip, legId) => itinerariesFor(trip, legId)[0] ?? null;
  // The itineraries no leg is handed any more, newest first: the earlier versions.
  function earlierItineraries(trip) {
    const current = new Set(legsOf(trip).map(l => itineraryFor(trip, l.id)).filter(Boolean));
    if (!legsOf(trip).length && allItineraries(trip)[0]) current.add(allItineraries(trip)[0]);
    return allItineraries(trip).filter(d => !current.has(d));
  }

  /* THE DAY-OF CONTACTS, the trip's list in its order: each a name, a phone,
     or both, and the contact it links. */
  const allContacts = trip => [...(trip?.trip_contacts || [])]
    .filter(c => clean(c.name) || clean(c.phone))
    .sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
    .map(c => ({ id: c.contact_id ?? null, name: clean(c.name), phone: clean(c.phone), leg_id: c.leg_id ?? null, row: c.id }));
  const contactsFor = (trip, legId) => forLeg(trip, legId, allContacts(trip));

  // A route's stops and vehicles, each in its order.
  const byPosition = (a, b) => (a.position ?? 0) - (b.position ?? 0);
  const stopsOfRoute = (trip, routeId) => (trip?.trip_stops || []).filter(s => s.route_id === routeId).sort(byPosition);
  const vehiclesOfRoute = (trip, routeId) => (trip?.trip_assignments || []).filter(a => a.route_id === routeId).sort(byPosition);

  window.SchedulerTripShape = {
    legsOf, legOf, firstLeg, legOfWord, legLabel, legOfRoute, forLeg, daysOf, isSplit, isPickup,
    isItinerary, allItineraries, itinerariesFor, itineraryFor, earlierItineraries,
    allContacts, contactsFor, stopsOfRoute, vehiclesOfRoute,
  };
})();

// ── past-midnight.js
/* ==========================================================================
   Rux Scheduler — PAST MIDNIGHT, the day each of a leg's times falls on
   --------------------------------------------------------------------------
   The one rule for a leg's times that carry no date: read in the order they
   happen, a time earlier on the clock than the last one before it is the
   next day's. The board's +1, the Route tab's Summary, the Detailed
   itinerary, the driver's road, the quote's words and the Route tab's stop
   order all count days by it, so 1:00 AM after an evening is never read as
   the morning the leg starts.

     daysPast(times)   the midnights passed at each of `times`, from the
                       first: a time is "HH:MM", or minutes after midnight,
                       and an empty one takes the count so far
     after(last, time) whether `time` is past a midnight after `last`
     forward(minutes)  each value moved on by whole days until it is not
                       before the one before it, an empty one kept empty

   Nothing here reads the page or the database, and it needs nothing loaded
   first. Its sample cases are in tools/check-past-midnight.mjs.
   ========================================================================== */
(() => {
  'use strict';

  const DAY = 1440;
  // Minutes after midnight, from "HH:MM", "HH:MM:SS" or a number; null for none.
  const minutesOf = t => {
    if (typeof t === 'number') return Number.isFinite(t) ? t : null;
    const m = /^(\d{1,2}):(\d{2})/.exec(String(t ?? ''));
    return m ? Number(m[1]) * 60 + Number(m[2]) : null;
  };

  const after = (last, time) => {
    const a = minutesOf(last), b = minutesOf(time);
    return a != null && b != null && b < a;
  };

  function daysPast(times) {
    let last = null, days = 0;
    return times.map(t => {
      const n = minutesOf(t);
      if (n == null) return days;
      if (last != null && n < last) days += 1;
      last = n;
      return days;
    });
  }

  function forward(minutes) {
    let prev = null;
    return minutes.map(v => {
      if (v == null) return null;
      let at = v;
      while (prev != null && at < prev) at += DAY;
      prev = at;
      return at;
    });
  }

  window.SchedulerPastMidnight = { minutesOf, after, daysPast, forward };
})();

// ── week.js
/* ==========================================================================
   Rux Scheduler — WEEK, where a trip sits on a week and what colour it paints
   --------------------------------------------------------------------------
   Loaded by the board and by the forms page and owned by neither: the board
   draws a week and the printed week puts the same week on paper, and a trip
   that covers different days, takes a different lane or paints a different
   colour in the two is a fault nobody sees until the sheet is on the wall.
   Nothing here reads the page or the database; each takes a trip as the
   database returns it.
   ========================================================================== */
(() => {
  'use strict';

  const DAY = 864e5;
  const parseISO = s => { const [y, m, d] = String(s).split('-').map(Number); return new Date(y, m - 1, d); };
  const daysBetween = (a, b) => Math.round((b - a) / DAY);

  // -- the palette ----------------------------------------------------------
  /* The trip colours, read by the board, the editor, the bar menu and the
     printed week. `value` is what `trips.trip_bar_color` stores and `hue` is
     the `scheduler-bar--*` class that paints it. Amber is the office's
     placeholder colour, for a trip not yet quoted or one whose customer has
     not settled its date or destination; billing.js says when an amber trip
     is a placeholder. */
  const TRIP_COLORS = [
    { value: 'teal', label: 'Teal', hue: 'teal' },
    { value: 'green', label: 'Green', hue: 'green' },
    { value: 'purple', label: 'Purple', hue: 'purple' },
    { value: 'amber', label: 'Placeholder', hue: 'amber' },
  ];
  // The colour a trip paints as, by its current name, or null for standard.
  const tripColorOf = trip => {
    const stored = String(trip.trip_bar_color || '').toLowerCase();
    return TRIP_COLORS.some(c => c.value === stored) ? stored : null;
  };
  /* Standard is the status colour: red for an unconfirmed trip, and for a
     confirmed one blue, or gray where the View menu's Confirmed trips in
     gray is on, which data.js sets through `confirmedHue`. */
  let confirmed = 'blue';
  const confirmedHue = hue => { confirmed = hue; };
  const standardHueOf = trip => (trip.confirmed === false ? 'red' : confirmed);

  // An override colour beats status, and status beats the confirmed colour.
  const hueFor = trip => TRIP_COLORS.find(c => c.value === tripColorOf(trip))?.hue
    ?? standardHueOf(trip);

  // -- placing --------------------------------------------------------------
  /* A leg's own stops in order, and the two that carry its times: the first
     `pickup` holds the departure in `depart_prev` and the last `return` the
     arrival in `arrive`. The board and the editor both use it, so they pick
     the same two; `timesOf` falls back to the trip's own time columns.

     A TRIP READ WITH ITS LEGS is read through trip-shape.js: the stops of
     the route named, or of the leg's first route with none named, the leg
     named by its key, its id, or by the old word a page still names it by.
     One read without them, from a page whose query does not ask for them
     yet, is read by the old word on each stop. */
  const SHAPE = window.SchedulerTripShape;
  const shaped = trip => Array.isArray(trip?.trip_legs) && !!SHAPE;
  const shapeLeg = (trip, key) => SHAPE.legOf(trip, key) ?? SHAPE.legOfWord(trip, key);
  const stopsOfLeg = (trip, leg, routeId = null) => {
    const routes = shaped(trip) ? shapeLeg(trip, leg)?.routes ?? [] : [];
    const route = routes.find(r => r.id === routeId) ?? routes[0];
    const stops = route ? SHAPE.stopsOfRoute(trip, route.id)
      : (trip.trip_stops || [])
        .filter(s => (s.leg || 'outbound') === leg)
        .sort((a, b) => (a.position ?? 0) - (b.position ?? 0));
    return {
      stops,
      pickup: stops.find(s => s.type === 'pickup') ?? stops[0],
      back: [...stops].reverse().find(s => s.type === 'return'),
    };
  };

  /* The midnights a one-day leg's return comes after its departure, by
     past-midnight.js's rule. The leg's times are read in the order they
     happen, the yard out, the spot, the group's departure, each stop and the
     yard back. The count starts at the group's departure, which is on the
     leg's day, so a yard departure the night before is not counted. A longer
     leg's end is on its last day. */
  const midnightsOf = (stops, pickup, back, depart) => {
    if (!back?.arrive) return 0;
    const rows = stops.slice(Math.max(stops.indexOf(pickup), 0), stops.indexOf(back) + 1);
    // The pickup row's yard departure, arrival and spot, then each row after it.
    const run = [depart, pickup?.arrive, pickup?.spot];
    for (const s of rows.slice(1)) run.push(s.depart_prev, s.arrive, s.spot);
    // The group's departure is the row after the pickup's `depart_prev`.
    const group = rows.length > 1 ? 3 : 0;
    const days = window.SchedulerPastMidnight.daysPast(run);
    return days.at(-1) - days[group];
  };

  /* The days before the group's that the bus leaves the yard: the pickup's
     yard departure is dated, and the group's day is its spot's, or the
     departure from the pickup's where it has no spot. Counted between the two
     saved days, so it holds while the leg's dates move in the editor. */
  const outDaysOf = (stops, pickup) => {
    const out = pickup?.depart_prev ? pickup.depart_prev_date : null;
    const group = pickup?.spot_date || stops[stops.indexOf(pickup) + 1]?.depart_prev_date || null;
    return out && group && out < group ? daysBetween(parseISO(out), parseISO(group)) : 0;
  };

  /* A route's times as saved, by its leg's key or old word and the route's
     id, the leg's first route with none named: the yard departure,
     the spot, the trip's end and the yard return, `nights`, the midnights a
     one-day leg's return comes after its departure, and `outDays`, the days
     before the leg's first that the bus leaves the yard. A leg with no pickup
     departure takes the trip's time column for the word it mirrors, and a
     leg that mirrors none has no departure. */
  const timesOf = (trip, leg, routeId = null) => {
    const { stops, pickup, back } = stopsOfLeg(trip, leg, routeId);
    const word = shaped(trip) ? shapeLeg(trip, leg)?.word ?? null : leg;
    const depart = pickup?.depart_prev || (word === 'outbound' ? trip.departure_time : word ? trip.return_time : null) || null;
    return {
      depart,
      back: back?.arrive || null,
      spot: pickup?.spot || null,
      end: back?.depart_prev || null,
      nights: midnightsOf(stops, pickup, back, depart),
      outDays: outDaysOf(stops, pickup),
    };
  };

  /* THE LATE RETURN, the office's, kept in `settings` as `late-return-v1`: a
     bus back at the yard before this hour of the morning came back the night
     before, so the day it is back on is not one the leg takes. Hour 0 counts
     no return as the night before. Its `night_hour` is the same rule at the
     other end, a PM hour: a bus that leaves the yard at or after it on the
     evening just before the leg's first day left for that day, so the evening
     it leaves on is not one the leg takes. Hour 12, midnight, counts no
     departure so. */
  const LATE_RETURN_HOUR = 4;
  const NIGHT_HOUR = 11;
  let lateBefore = LATE_RETURN_HOUR * 60;
  let nightFrom = (12 + NIGHT_HOUR) * 60;
  const setLateReturn = value => {
    const hour = Number(value?.hour);
    lateBefore = (value?.hour != null && Number.isFinite(hour) && hour >= 0 && hour <= 12 ? hour : LATE_RETURN_HOUR) * 60;
    const night = Number(value?.night_hour);
    nightFrom = (12 + (value?.night_hour != null && Number.isInteger(night) && night >= 1 && night <= 12 ? night : NIGHT_HOUR)) * 60;
  };
  // The hour as minutes after midnight, for a route's model.
  const lateReturn = () => lateBefore;

  const dayFrom = (day, n) => {
    const d = parseISO(day);
    d.setDate(d.getDate() + n);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  /* THE OFFICE'S CLOCK. A McAllen date and time as an instant, whatever zone
     the browser is in: the offset is found at a first guess and checked once
     more, which settles a guess across a clock change. The night the clocks
     go back, 1:00 to 1:59 comes twice, and `later` takes the second reading
     where the first is otherwise taken, so a leg leaves at the first and is
     back at the second, and a bus is never thought late or home an hour
     early. A leg leaves the yard at its departure on the first day it takes,
     or that day's start with none; it is back at its yard return, on the day after `to` when that
     is past midnight, or with no return at the late-return hour after its
     last day. */
  // Made once: a draw reads the office's clock about 1,600 times.
  const OFFICE_WALL = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', hourCycle: 'h23',
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  const officeWall = ms => {
    const parts = OFFICE_WALL.formatToParts(new Date(ms));
    const n = t => Number(parts.find(p => p.type === t)?.value);
    return Date.UTC(n('year'), n('month') - 1, n('day'), n('hour'), n('minute'));
  };
  const HOUR_MS = 36e5;
  const officeInstant = (day, time, later = false) => {
    const [y, m, d] = String(day).split('-').map(Number);
    const [h, min] = String(time || '00:00').split(':').map(Number);
    const asUtc = Date.UTC(y, m - 1, d, h || 0, min || 0);
    const first = asUtc - (officeWall(asUtc) - asUtc);
    const at = asUtc - (officeWall(first) - first);
    // A wall time read twice is an hour either side of `at`, which is one of them.
    if (!later) return officeWall(at - HOUR_MS) === asUtc ? at - HOUR_MS : at;
    return officeWall(at + HOUR_MS) === asUtc ? at + HOUR_MS : at;
  };
  const departAt = leg => officeInstant(dayFrom(leg.from, -(leg.departDays ?? 0)), leg.depart);
  const backAt = leg => (leg.back
    ? officeInstant(dayFrom(leg.to, leg.backDays ?? 0), leg.back, true)
    : officeInstant(dayFrom(leg.to, 1), `${Math.floor(lateBefore / 60)}:${lateBefore % 60}`, true));

  /* THE DAYS A LEG TAKES, from its dates and its times as `timesOf` gives
     them. The bus is back on the leg's last day, or the day after when the
     yard return is earlier on the clock than the trip's end; on a one-day leg
     it is back as many days on as its times pass midnight. Back before the
     late-return hour, the leg takes the days up to the one before and
     `backDays` says how many days after its last the bus is back, the bar's
     +1; back at or after that hour, it takes the day it is back on. A leg
     with no yard return takes its own last day. A bus that leaves the yard
     before the leg's first day, to be at a far pickup by its spot, takes
     from the day it leaves, `outDays` before, since it is out of the yard
     from then on; one that leaves the evening just before at or after the
     night hour takes from the leg's first day, and `departDays` says how
     many days before it the bus leaves, the bar's −1. */
  /* The most days before its first that a leg's bus leaves the yard, so a
     read of the trips on a range of days reaches this far past its last. */
  const AHEAD_DAYS = 2;
  const takes = (from, to, times) => {
    const PAST = window.SchedulerPastMidnight;
    const night = times?.outDays === 1 && (PAST.minutesOf(times.depart) ?? -1) >= nightFrom;
    const out = night ? { from, outDays: 0, departDays: 1 }
      : times?.outDays > 0 ? { from: dayFrom(from, -times.outDays), outDays: times.outDays, departDays: 0 }
      : { from, outDays: 0, departDays: 0 };
    const back = PAST.minutesOf(times?.back);
    if (back == null) return { ...out, to, backDays: 0 };
    const backOn = dayFrom(to, to > from ? (PAST.after(times.end, times.back) ? 1 : 0) : times.nights ?? 0);
    return { ...out, ...(back < lateBefore && backOn > from ? { to: dayFrom(backOn, -1), backDays: 1 } : { to: backOn, backDays: 0 }) };
  };

  // A leg saved with its end before its start is read as its start day, so it
  // still has a bar to open and put right.
  const lastDay = (from, to) => (to && to >= from ? to : from);
  /* A trip's legs, each with `starts` and `ends`, the first and last day as
     saved, `number`, from 1 in date order, and `routes`, each route's own
     times and the days its buses take, with `routeId`, `routeName` and
     `routeNumber`; a trip read without its legs has one route with no id.
     A leg takes `from` to `to`, the first day any of its routes takes to
     the last, and carries its first route's times, which a page reading a
     bus reads from its route instead, through `rangeOf`. `key` tells the
     legs apart: the leg's id on a trip read with its legs, which gives
     `legId` too, and the old word on one that is not, such as a draft. A
     leg that mirrors an old word carries it in `leg`, which the old columns
     are read by, and a leg that mirrors none carries null. */
  const legsOf = trip => {
    const legs = [];
    const add = (leg, from, end, count, more = {}, routes = [null]) => {
      const ends = lastDay(from, end);
      const timed = routes.map((r, i) => {
        const times = timesOf(trip, more.key ?? leg, r?.id ?? null);
        return { routeId: r?.id ?? null, routeName: r?.name || null, routeNumber: i + 1, ...times, ...takes(from, ends, times) };
      });
      const { routeId, routeName, routeNumber, ...first } = timed[0];
      legs.push({ leg, key: leg, number: legs.length + 1, starts: from, ends, count, ...first, ...more,
        from: timed.reduce((d, r) => (r.from < d ? r.from : d), first.from),
        to: timed.reduce((d, r) => (r.to > d ? r.to : d), first.to),
        routes: timed });
    };
    if (shaped(trip)) {
      for (const l of SHAPE.legsOf(trip)) {
        if (l.start) {
          add(l.word, l.start, l.end, l.busCount || 1,
            { legId: l.id, key: l.id, number: l.number, hotelBooked: l.hotelBooked, hotelNumber: l.hotelNumber },
            l.routes.length ? l.routes : [null]);
        }
      }
      return legs;
    }
    const hotel = word => ({ hotelBooked: !!trip[`hotel_booked_${word}`], hotelNumber: trip[`hotel_itinerary_number_${word}`] || null });
    if (trip.start_date) add('outbound', trip.start_date, trip.end_date, trip.bus_count || 1, hotel('outbound'));
    if (trip.return_start_date) add('return', trip.return_start_date, trip.return_end_date, trip.return_bus_count || trip.bus_count || 1, hotel('return'));
    return legs;
  };
  /* The key of the leg a vehicle runs on: on a trip read with its legs, its
     route's leg, or the leg its old word names while the page has made it
     and not yet read it back with its route; on one that is not, the word. */
  const legKeyOfVehicle = (trip, a) => (!shaped(trip) ? a?.leg || 'outbound'
    : (a?.route_id ? SHAPE.legOfRoute(trip, a.route_id) : SHAPE.legOfWord(trip, a?.leg))?.id ?? null);
  /* ONE ROUTE OF A LEG, as a leg: the leg with that route's times and the
     days its buses take, `routeId`, `routeName`, `routeNumber`, and
     `routeCount`, how many routes the leg has. A route the leg lacks, or
     none named, is its first, as a vehicle a page has made and not yet read
     back with its route is on. */
  const rangeOf = (leg, routeId = null) => {
    if (!leg) return null;
    const route = leg.routes.find(r => r.routeId === routeId) ?? leg.routes[0];
    return { ...leg, ...route, routeCount: leg.routes.length };
  };
  /* A trip's leg by its key, or by the old word a link or row still names;
     with a route named, that route of it, as `rangeOf` gives it. */
  const legByKey = (trip, key, routeId) => {
    const leg = legsOf(trip).find(l => l.key === key)
      ?? (key == null ? null : legsOf(trip).find(l => l.leg === key)) ?? null;
    return routeId === undefined ? leg : rangeOf(leg, routeId);
  };
  /* Every route of every leg of a trip, each as `rangeOf` gives it, with
     the vehicles on it in position order: a bus's days and times are its
     route's. A vehicle with no route yet is on its leg's first. */
  const rangesOf = trip => legsOf(trip).flatMap(leg => {
    const vehicles = (trip.trip_assignments || []).filter(a => legKeyOfVehicle(trip, a) === leg.key)
      .sort((x, y) => (x.position ?? 0) - (y.position ?? 0));
    return leg.routes.map((r, i) => ({
      ...rangeOf(leg, r.routeId),
      vehicles: vehicles.filter(a => (leg.routes.some(x => x.routeId === a.route_id) ? a.route_id === r.routeId : i === 0)),
    }));
  });

  const clip = (from, to, weekStart, weekEnd) => {
    const a = parseISO(from), b = parseISO(to);
    if (b < weekStart || a > weekEnd) return null;
    const vs = a < weekStart ? weekStart : a;
    const ve = b > weekEnd ? weekEnd : b;
    return {
      start: daysBetween(weekStart, vs),
      span: daysBetween(vs, ve) + 1,
      fromPrev: a < weekStart,
      toNext: b > weekEnd,
    };
  };

  // Greedy lane packing: the first lane whose last occupied day ends before
  // this bar starts. Bars are sorted by start first, which is what makes one
  // pass enough.
  function assignLanes(bars) {
    const lastEnd = [];
    bars.sort((x, y) => x.place.start - y.place.start || x.place.span - y.place.span);
    for (const bar of bars) {
      let lane = 0;
      while (lastEnd[lane] !== undefined && lastEnd[lane] >= bar.place.start) lane++;
      bar.lane = lane;
      lastEnd[lane] = bar.place.start + bar.place.span - 1;
    }
    return lastEnd.length || 1;
  }

  window.SchedulerWeek = {
    TRIP_COLORS, tripColorOf, standardHueOf, hueFor, confirmedHue,
    stopsOfLeg, timesOf, legsOf, rangeOf, rangesOf, legKeyOfVehicle, legByKey, takes, setLateReturn, lateReturn, clip, assignLanes,
    officeInstant, departAt, backAt, AHEAD_DAYS,
  };
})();

// ── road.js
/* ==========================================================================
   Rux Scheduler — ROAD, where a bus out on its trip is and where it goes next
   --------------------------------------------------------------------------
   Loaded by the board and the Live map, and owned by neither, so a bar and a
   map pin never say two different things about one bus. Nothing here draws.

   `span(leg)` is when a leg's bus counts as out on it, and `isOut(bus, span)`
   whether it is now.

   `live(client)` asks the samsara-now Edge Function what every bus is doing
   and keeps each bus's path, the GPS points since its leg left the yard, by
   asking each time for the points since the last one it has.

   `stopsOf(trip, leg, route)` lists a route's stops in order with the time
   the bus is due at each, the leg named by its key, week.js's, or by its old
   word, and the route by its id, the leg's first with none: the
   pickup at its Spot, every other stop and the yard return
   at their Arrives. `whereOn(stops, path, bus)` follows the path through
   them: a stop is reached when the bus comes within a quarter mile of it, in
   order, and no sooner than two hours before it is due, so a bus driving
   past a later stop on its way has not reached it; a bus that stands ten
   minutes within that quarter mile is at the stop however early, the
   stops before it skipped, but for the yard return. A pickup is also reached
   by a bus that stands still for two minutes within half a mile of it, since
   a pin on a campus or a stadium is rarely where the bus loads, and passed
   by one that stood still five minutes within a mile and a half of it and is
   now more than two and a half miles off, since it loaded at a lot further
   out and drove on. The next stop is the first after the last one reached
   that has a map point. A bus with no path yet is nowhere known on its leg.
   `nextOn(stops, bus, eta)` is that reading as the bar and the map use it:
   { stops, where, stop, at, arrival, late }, or null with no path.

   `arrivals(drive)` works out when a bus gets to a stop from where it is,
   Geoapify's drive slowed by the office's percent, asked at most once every
   five minutes for each bus and stop, so two legs out on one bus never ask
   in turn for each other's stop.
   A bus is late only to a pickup, when it gets there more than 10 minutes
   after its spot; every other stop moves with the day, so nobody is told
   how late the bus is to it.

   `pickupLate(due, at)` says whether a bus that reached its pickup at `at`,
   as samsara-miles finds it in the GPS history, was on time: at or before it
   was due, which earns the Driver seat `ON_TIME_PAY` dollars.
   ========================================================================== */
(() => {
  'use strict';

  const NEAR_MILES = 0.25;
  const EARLY_MS = 2 * 3600e3;
  const ARRIVAL_EVERY = 5 * 60e3;
  // The furthest back a path is asked from, so a leg days long loads quickly.
  const PATH_BACK = 12 * 3600e3;
  const LATE_MIN = 10;
  /* Driving time left this short is low and drawn amber, on the wheel, the
     tips, the cards, the driver rail and the live page alike: under two hours
     a driver cannot take one more leg out and back. */
  const LOW_LEFT = 2 * 3600e3;
  /* A bus parked this near a pickup is there. Parked is standing still this
     long: points within GPS wander of each other, or two points this little
     apart with that long between them, since Samsara sends few points from a
     bus that sits, or the engine idle or off that long. */
  const PARKED_MILES = 0.5;
  const STILL_MILES = 0.03;
  const CREPT_MILES = 0.15;
  const PARKED_MS = 2 * 60e3;
  /* A bus that stood this long this near a pickup, and is now further off
     than GONE_MILES, loaded there and left: long enough that a red light or
     a slow lane does not count, far enough that a bus still finding its way
     in has not gone. */
  const AREA_MILES = 1.5;
  const LOADED_MS = 5 * 60e3;
  const GONE_MILES = 2.5;
  /* A bus that stands this long within a quarter mile of a stop is there
     however early it is, and the stops before it were skipped: long enough
     that a light or a slow pass by it does not count. */
  const SKIP_MS = 10 * 60e3;

  // The miles between two points as the crow flies; each is [lat, lng].
  const miles = (a, b) => {
    const rad = Math.PI / 180;
    const dLat = (b[0] - a[0]) * rad, dLng = (b[1] - a[1]) * rad;
    const h = Math.sin(dLat / 2) ** 2 + Math.cos(a[0] * rad) * Math.cos(b[0] * rad) * Math.sin(dLng / 2) ** 2;
    return 3958.8 * 2 * Math.asin(Math.sqrt(h));
  };

  const dayFrom = (day, n) => {
    const [y, m, d] = String(day).split('-').map(Number);
    const t = new Date(Date.UTC(y, m - 1, d + n));
    return t.toISOString().slice(0, 10);
  };

  /* A route's stops in order, from the pickup to the yard return, each with
     its name, its map point and when the bus is due there, an instant on
     the office's clock or null. A time saved with no date is on the leg's
     first day, or the next day where it is earlier on the clock than the
     time before it, by past-midnight.js's rule. A stop is never due before
     the one before it: in the hour the clocks go back it takes the second
     reading of the time, and a dated time that would still be is on the next
     day, since an older row dates a time past midnight a day early. `leaves`
     is when the bus leaves a stop, saved on the stop after it as that one's
     `depart_prev`, on the first day from its own date, or the stop's, that
     is not before the arrival, as a due time is; null where the bus leaves
     as it gets there, as the itinerary prints an arrival alone. */
  function stopsOf(trip, leg, route = null) {
    const W = window.SchedulerWeek;
    const legOf = W.legByKey(trip, leg, route);
    if (!legOf) return [];
    const { stops, pickup } = W.stopsOfLeg(trip, legOf.key, route);
    let day = legOf.from, last = null, before = null;
    return stops.slice(Math.max(stops.indexOf(pickup), 0)).map((s, i, legStops) => {
      const [time, date] = s.type === 'pickup' ? (s.spot ? [s.spot, s.spot_date] : [s.depart_prev, s.depart_prev_date])
        : [s.arrive, s.arrive_date];
      let due = null;
      if (time) {
        if (date) day = date;
        else if (window.SchedulerPastMidnight.after(last, time)) day = dayFrom(day, 1);
        last = time;
        due = W.officeInstant(day, time);
        if (before != null && due < before) due = W.officeInstant(day, time, true);
        while (before != null && due < before) { day = dayFrom(day, 1); due = W.officeInstant(day, time); }
        before = due;
      }
      const after = legStops[i + 1];
      let leaves = null;
      if (due != null && after?.depart_prev) {
        let on = after.depart_prev_date || day;
        leaves = W.officeInstant(on, after.depart_prev);
        while (leaves < due) { on = dayFrom(on, 1); leaves = W.officeInstant(on, after.depart_prev); }
        if (leaves === due) leaves = null;
      }
      return {
        key: String(s.id ?? `${leg}-${s.position}`),
        type: s.type,
        name: s.type === 'return' ? 'Yard' : (s.name || s.address || '').trim(),
        point: s.lat != null && s.lng != null ? [Number(s.lat), Number(s.lng)] : null,
        due,
        leaves,
      };
    });
  }

  /* Where a bus is on its leg, from its path, the points [lat, lng, ms]
     oldest first: `reached`, the index of the last stop it has reached or -1,
     `at`, true while it is still within a quarter mile of that stop, and
     `next`, the index of the first stop after it with a map point, or -1
     when there is none left; and `arrived`, by a stop's index, when the bus
     got there: the first point within reach, or where it came to rest for a
     stop reached by standing, unknown for a stop taken as reached because
     it was due before the path begins. A stop reached is left behind once the bus is
     out of its reach, and only then can the next be reached, so a bus waiting
     at a pickup it comes back to at the end has not come back yet. The path
     starts where the bus waited before it left, the yard, and nothing is
     reached until the bus has left there, so a short trip's yard return is
     not reached as the bus pulls out. A bus that has stood SKIP_MS within
     a quarter mile of a later stop has reached it, however early, and
     skipped the stops between; the yard return waits for its time, since a
     bus may stop at the yard before it is done. A path begins at most twelve hours
     back, so a stop due before it begins is taken as reached. A pickup is
     also reached by a bus that has stood still within half a mile of it,
     and left behind once the bus is half a mile off; and it is passed, the
     bus never at it, once a bus that stood still five minutes within a mile
     and a half of it is two and a half miles off. `bus`, samsara-now's
     reading, ends the path where it stands while it is stopped, idle or
     off, standing as long as its engine has idled or been off by `now`,
     so a bus that sends no new points still counts its wait. With no
     `path` at all, as before the board has asked for the bus's, where the
     bus is on its leg is not known, and the answer is null, so a bus just
     drawn is never read as one that has reached nothing. */
  function whereOn(stops, path, bus = null, now = Date.now()) {
    if (!path) return null;
    let reached = -1, inside = false, left = false, reach = NEAR_MILES, rest = null, before = null, waited = -1, waitedAt = null;
    const arrived = [];
    const points = [...(path || [])];
    const standing = bus?.lat != null && bus?.lng != null && (bus.mph === 0 || bus.engine === 'idle' || bus.engine === 'off');
    const still = standing && (bus.engine === 'idle' || bus.engine === 'off') ? now - Date.parse(bus.engine_at) || 0 : 0;
    let last = null;
    if (standing) {
      last = [bus.lat, bus.lng, Math.max(Date.parse(bus.seen) || now, (points.at(-1)?.[2] ?? -Infinity) + 1)];
      points.push(last);
    }
    const begins = points[0]?.[2];
    if (begins != null) stops.forEach((s, i) => { if (s.due != null && s.due < begins) reached = i; });
    for (const p of points) {
      left ||= miles(points[0], p) > NEAR_MILES;
      // Where the bus came to rest, kept while it stays within GPS wander of it.
      if (!rest || miles(rest, p) > STILL_MILES) rest = p;
      // How long the bus has stood here: since it came to rest, across a
      // long quiet with little ground between two points, or as its engine says.
      const crept = before && p[2] - before[2] >= PARKED_MS && miles(before, p) <= CREPT_MILES;
      const stood = Math.max(p[2] - rest[2], crept ? p[2] - before[2] : 0, p === last ? still : 0);
      before = p;
      if (!left) continue;
      if (inside && miles(stops[reached].point, p) > reach) inside = false;
      if (inside) continue;
      if (waited > reached && miles(stops[waited].point, p) > GONE_MILES) { reached = waited; arrived[reached] = waitedAt; continue; }
      for (let j = reached + 1; j < stops.length; j++) {
        const s = stops[j];
        if (!s.point) continue;
        const d = miles(s.point, p);
        if (s.due != null && p[2] < s.due - EARLY_MS) {
          if (s.type !== 'return' && stood >= SKIP_MS && d <= NEAR_MILES) { reached = j; arrived[j] = rest[2]; inside = true; reach = NEAR_MILES; break; }
          continue;
        }
        if (d <= NEAR_MILES) { reached = j; arrived[j] = p[2]; inside = true; reach = NEAR_MILES; break; }
        if (s.type !== 'pickup') continue;
        if (stood >= PARKED_MS && d <= PARKED_MILES) { reached = j; arrived[j] = rest[2]; inside = true; reach = PARKED_MILES; break; }
        if (stood >= LOADED_MS && d <= AREA_MILES) { if (waited !== j) waitedAt = rest[2]; waited = j; }
      }
    }
    const next = stops.findIndex((s, i) => i > reached && s.point);
    return { reached, at: inside, next, arrived };
  }

  /* A leg's stretch on the road, from its yard-out to its yard-back as
     week.js reads both on the office's clock, padded two hours at each end:
     a bus counts as out on its leg inside the padding while its engine runs,
     and between yard-out and yard-back whatever the engine is doing. */
  const MARGIN = 2 * 3600e3;
  const span = leg => {
    if (!leg?.from || !leg?.to) return null;
    const W = window.SchedulerWeek;
    const from = W.departAt(leg);
    return [from - MARGIN, Math.max(W.backAt(leg), from) + MARGIN];
  };
  const isOut = (bus, [from, to], now = Date.now()) => !!bus && from <= now && now <= to
    && (bus.engine === 'on' || bus.engine === 'idle' || (from + MARGIN <= now && now <= to - MARGIN));

  // An instant as the office's clock reads it, "17:40".
  const OFFICE_CLOCK = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', hourCycle: 'h23', hour: '2-digit', minute: '2-digit' });
  const clockOf = ms => OFFICE_CLOCK.format(new Date(ms));

  // How many minutes late to `stop` a bus that gets there at `arrival` is:
  // 0 on time, or for any stop but a pickup.
  const lateBy = (stop, arrival) => {
    if (stop?.type !== 'pickup' || stop.due == null || arrival == null) return 0;
    const min = Math.round((arrival - stop.due) / 60e3);
    return min > LATE_MIN ? min : 0;
  };

  // 0 for a pickup reached on time, the minutes late, or null when either
  // time is missing.
  const ON_TIME_PAY = 20;
  const pickupLate = (due, at) => (due == null || at == null ? null
    : at <= due ? 0 : Math.max(1, Math.round((at - due) / 60e3)));

  /* Each bus's arrival at its next stop, as an instant: `get(busId, stop,
     here)` hands back the last one worked out for that bus and stop, and asks
     again when it is five minutes old, or at once for a stop not asked yet.
     Kept by bus and stop, since a bus out on two legs at once asks for two
     stops on every draw, and an answer that redraws must not set off another
     ask. `drive` is (from, to) => Promise<minutes | null>, from places.js and
     the route times; `onChange` is called when an answer comes. */
  function arrivals(drive, onChange, now = () => Date.now()) {
    const known = new Map();
    return {
      get(busId, stop, here) {
        if (!stop?.point || !here) return null;
        const id = `${busId}\u0000${stop.key}`;
        const had = known.get(id);
        if (!had || (!had.asking && now() - had.asked >= ARRIVAL_EVERY)) {
          const entry = { asked: now(), asking: true, at: had?.at ?? null };
          known.set(id, entry);
          Promise.resolve(drive({ lat: here[0], lng: here[1] }, { lat: stop.point[0], lng: stop.point[1] }))
            .then(min => { if (min != null) entry.at = entry.asked + min * 60e3; })
            .catch(() => {})
            .finally(() => { entry.asking = false; onChange?.(); });
          return entry.at;
        }
        return had.at;
      },
    };
  }

  /* What samsara-now says about every bus, with each bus's path kept between
     answers. `ask(since)` takes { busId: ms } for the buses out on a leg, the
     time each left the yard, and asks for the points after the newest it
     has, twelve hours back at most; a bus whose leg starts at another time
     starts a new path, which
     the board and the map start two hours before the leg leaves the yard,
     while the bus is still there. It
     resolves to the answer with every bus's `path` whole, or throws the
     function's error. A bus out whose path has never come, because
     Samsara would not give it, has none, which whereOn reads as not known;
     once one has come, an answer without it adds nothing, and the next ask
     goes on from the newest point held, so no stretch is missed. */
  function live(client, now = () => Date.now()) {
    const paths = new Map();   // busId -> { from, points }
    return {
      async ask(since = {}) {
        const want = {};
        for (const [busId, from] of Object.entries(since)) {
          const had = paths.get(busId);
          if (!had || had.from !== from) paths.set(busId, { from, points: [], read: false });
          const last = paths.get(busId).points.at(-1);
          want[busId] = new Date(last ? last[2] + 1 : Math.max(from, now() - PATH_BACK)).toISOString();
        }
        for (const busId of [...paths.keys()]) if (!(busId in since)) paths.delete(busId);
        const r = await client.functions.invoke('samsara-now', { body: Object.keys(want).length ? { paths: want } : {} });
        if (r.error) throw r.error;
        for (const bus of r.data?.buses ?? []) {
          const held = paths.get(bus.bus_id);
          if (!held) continue;
          if (Array.isArray(bus.path)) held.read = true;
          held.points.push(...(bus.path ?? []).filter(p => !held.points.length || p[2] > held.points.at(-1)[2]));
          bus.path = held.read ? held.points : undefined;
        }
        return r.data;
      },
    };
  }

  /* Where a bus is on its leg's stops, as the board's bar and the Live map
     both read it: `whereOn`'s answer, the stop it is at or goes to next, and,
     on the way, when it gets there by `eta`, an `arrivals`, and how late. */
  function nextOn(stops, bus, eta) {
    const where = whereOn(stops, bus.path, bus);
    if (!where) return null;
    if (where.at) return { stops, where, stop: stops[where.reached], at: true };
    if (where.next < 0) return { stops, where, stop: null };
    const stop = stops[where.next];
    const arrival = eta.get(bus.bus_id, stop, bus.lat != null ? [bus.lat, bus.lng] : null);
    return { stops, where, stop, at: false, arrival, late: lateBy(stop, arrival) };
  }

  window.SchedulerRoad = { NEAR_MILES, PARKED_MILES, LATE_MIN, LOW_LEFT, MARGIN, miles, span, isOut, stopsOf, whereOn, nextOn, clockOf, lateBy, ON_TIME_PAY, pickupLate, arrivals, live };
})();

export default window;
